// Parse the last line of stdout (the synthesis JSON). Earlier lines are
// runtime log noise from python (logging.basicConfig writes to stderr,
// but defensively we still take the last JSON-looking line).
const stdout = $input.first().json.stdout || '';
const lines = stdout.split('\n').map(l => l.trim()).filter(Boolean);
let synth = null;
for (let i = lines.length - 1; i >= 0; i--) {
  if (lines[i].startsWith('{') && lines[i].endsWith('}')) {
    try { synth = JSON.parse(lines[i]); break; } catch (_) {}
  }
}
if (!synth) {
  return [{ json: {
    parsed: false,
    raw_stdout_tail: lines.slice(-5).join('\n'),
    exit_code: $input.first().json.exitCode,
  }}];
}
synth.parsed = true;
synth.exit_code = $input.first().json.exitCode ?? null;
return [{ json: synth }];
